/* cerca_radici.c — ricottura (esplorazione, NON prova) sulla famiglia "radici pari / dispari rimossi" per Q_9.
   Stato: R sottoinsieme dei vertici pari (radici), B sottoinsieme dei dispari (rimossi da S).
   S = R + (dispari \ B) deve essere una foresta indotta; etichette: S in ordine di foresta, poi B, poi i pari non radici.
   Costo esatto dell'etichettatura (se S e' foresta): |S| + sum_b max(1,k_b) + sum_e ( contributi dei vicini dispari ),
   con k_b = numero di radici adiacenti a b. Penalita' lambda per ciclo residuo in S.
   Uso: ./cerca_radici seme passi t0 t1 [stato_iniziale.txt]  -> salva migliore_radici_<seme>.txt (512 righe: 0=S,1=B,2=R,3=pari non radice) */
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#define D 9
#define N (1<<D)
static int tipo[N];   /* pari: 2=radice, 3=non radice; dispari: 0=in S, 1=in B */
static int parent[N];
static int find(int x){ while(parent[x]!=x){ parent[x]=parent[parent[x]]; x=parent[x]; } return x; }
static int peso(int v){ return __builtin_popcount(v); }

/* Costo esatto della etichettatura indotta + lambda * cicli residui. */
static long valuta(int lambda, int *cicli_out){
    int k[N]; long tot=0; int cicli=0;
    for(int v=0; v<N; v++) parent[v]=v;
    for(int b=0;b<N;b++) if(peso(b)&1){ k[b]=0; for(int i=0;i<D;i++) if(tipo[b^(1<<i)]==2) k[b]++; }
    for(int v=0; v<N; v++){
        if(peso(v)&1){ if(tipo[v]==0) tot+=1; else tot+=(k[v]>1?k[v]:1); }
        else if(tipo[v]==2){ tot+=1;
            for(int i=0;i<D;i++){ int o=v^(1<<i); if(tipo[o]==0){ int a=find(v),c=find(o); if(a==c) cicli++; else parent[a]=c; } } }
        else { for(int i=0;i<D;i++){ int o=v^(1<<i); tot += (tipo[o]==0||k[o]<2)?1:k[o]; } }
    }
    *cicli_out=cicli; return tot + (long)lambda*cicli;
}

int main(int argc, char **argv){
    int seme=atoi(argv[1]); long passi=atol(argv[2]); double t0=atof(argv[3]), t1=atof(argv[4]); srand(seme);
    for(int v=0; v<N; v++) tipo[v]=(peso(v)&1)?0:3;
    if(argc>5){ FILE *f=fopen(argv[5],"r"); for(int v=0; v<N; v++) fscanf(f,"%d",&tipo[v]); fclose(f); }
    int lambda=40, cicli; long cur=valuta(lambda,&cicli), best=1L<<40; int bestT[N];
    if(cicli==0){ best=cur; memcpy(bestT,tipo,sizeof(tipo)); }
    for(long s=0;s<passi;s++){
        double t=t0*pow(t1/t0,(double)s/passi);
        int v=rand()%N; int vecchio=tipo[v];
        tipo[v] = (peso(v)&1) ? 1-vecchio : 5-vecchio;
        int c2; long nuovo=valuta(lambda,&c2);
        if(nuovo<=cur || (double)rand()/RAND_MAX < exp((cur-nuovo)/t)){ cur=nuovo; cicli=c2;
            if(cicli==0 && cur<best){ best=cur; memcpy(bestT,tipo,sizeof(tipo));
                int nr=0,nb=0; for(int u=0;u<N;u++){ nr+=tipo[u]==2; nb+=tipo[u]==1; }
                fprintf(stderr,"seme %d passo %ld: costo %ld |R|=%d |B|=%d\n",seme,s,best,nr,nb); } }
        else tipo[v]=vecchio;
    }
    char nome[64]; sprintf(nome,"migliore_radici_%d.txt",seme); FILE *f=fopen(nome,"w");
    for(int v=0; v<N; v++) fprintf(f,"%d\n",bestT[v]); fclose(f);
    printf("seme %d: costo migliore %ld\n",seme,best); return 0;
}

/* ricottura_etichette.c — ricottura simulata (esplorazione, NON prova) direttamente sulle etichettature di Q_9.
   Stato: permutazione ordine[0..511] (vertice con etichetta i). Mossa: scambio di due etichette. Punteggio esatto:
   conteggio dei cammini in salita con aritmetica intera (p(v) = [valle] + somma p sui vicini minori).
   Uso: ./ricottura_etichette seme passi t0 t1 [etichettatura_iniziale.txt (512 stringhe 0/1 separate da virgola)] */
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#define D 9
#define N (1<<D)
static int ordine[N], etichetta[N];
static long long p[N];

/* Conteggio esatto dei cammini in salita. */
static long long conta(void){
    long long tot=0;
    for(int i=0;i<N;i++){ int v=ordine[i]; long long s=0; int valle=1;
        for(int j=0;j<D;j++){ int u=v^(1<<j); if(etichetta[u]<i){ s+=p[u]; valle=0; } }
        p[v]= valle?1:s; tot+=p[v]; }
    return tot;
}
static int da_stringa(const char *s){ int v=0; for(int i=0;i<D;i++) if(s[i]=='1') v|=1<<i; return v; }

int main(int argc,char**argv){
    int seme=atoi(argv[1]); long passi=atol(argv[2]); double t0=atof(argv[3]), t1=atof(argv[4]); srand(seme);
    for(int i=0;i<N;i++) ordine[i]=i;
    if(argc>5){ FILE*f=fopen(argv[5],"r"); char s[16]; for(int i=0;i<N;i++){ fscanf(f,"%[01],",s); ordine[i]=da_stringa(s);} fclose(f); }
    else for(int i=N-1;i>0;i--){ int j=rand()%(i+1); int t=ordine[i]; ordine[i]=ordine[j]; ordine[j]=t; }
    for(int i=0;i<N;i++) etichetta[ordine[i]]=i;
    long long cur=conta(), best=cur; int bestO[N]; memcpy(bestO,ordine,sizeof(ordine));
    fprintf(stderr,"seme %d inizio %lld\n",seme,cur);
    for(long k=0;k<passi;k++){
        double t=t0*pow(t1/t0,(double)k/passi);
        int i=rand()%N, j=rand()%N; if(i==j) continue;
        int a=ordine[i], b=ordine[j]; ordine[i]=b; ordine[j]=a; etichetta[b]=i; etichetta[a]=j;
        long long nuovo=conta();
        if(nuovo<=cur || (double)rand()/RAND_MAX<exp((double)(cur-nuovo)/t)){ cur=nuovo;
            if(cur<best){ best=cur; memcpy(bestO,ordine,sizeof(ordine)); fprintf(stderr,"seme %d passo %ld: %lld\n",seme,k,best);} }
        else { ordine[i]=a; ordine[j]=b; etichetta[a]=i; etichetta[b]=j; }
    }
    char nome[64]; sprintf(nome,"migliore_etichette_%d.txt",seme); FILE*f=fopen(nome,"w");
    for(int i=0;i<N;i++){ for(int j=0;j<D;j++) fputc((bestO[i]>>j)&1?'1':'0',f); fputc(i<N-1?',':'\n',f);} fclose(f);
    printf("seme %d: migliore %lld\n",seme,best); return 0;
}
